    correction: [{"quoi":"القاعدة","math":"نرتّب القيم تصاعديا ; إذا كان N فرديا فالموسّط هو القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N+1</span><span class=\"den\">2</span></span></span>، و إذا كان زوجيا فهو معدّل القيمتين ذواتي الرتبتين <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> + 1</span>"},{"quoi":"نحسب التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 47</span>"},{"quoi":"و هو فردي","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N + 1</span><span class=\"den\">2</span></span> = 24</span>"},{"quoi":"نكوّن التكرارات المتراكمة الصاعدة","math":"<span dir=\"ltr\" class=\"expr\">ca = 8</span>"},{"quoi":"و نواصل إلى","math":"<span dir=\"ltr\" class=\"expr\">ce = 47</span>"},{"quoi":"نقرأ القيمة ذات الرتبة <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N+1</span><span class=\"den\">2</span></span></span>","math":"الرتبة 24 تقابل القيمة 5"},{"quoi":"و هي وحدها","math":"لا حاجة إلى رتبة ثانية"},{"quoi":"النتيجة","math":"الموسّط يساوي <span dir=\"ltr\" class=\"expr\">Me = 5</span>"}],
